-- Jibon Rokkha — 0008_demo_seed.sql
-- DEMO DATA ONLY. No CREATE TABLE. Safe to re-run (idempotent where possible).
-- Counts: 8 divisions, 16 districts, 48 upazilas, 10 specialties,
--         1200 profiles, 800 donors, 60 doctors, 200 blood_requests = 2332 rows.
-- Run with service_role / as migration role (bypasses RLS).
-- psql: \i migrations/0008_demo_seed.sql
-- =============================================================================

-- -----------------------------------------------------------------------------
-- ADDRESS CHECK: profiles (registered person) already has address columns
-- per 0001_schema.sql: present_address + permanent_address.
-- This is a harmless no-op if they exist; adds a flat 'address' alias only if missing.
-- -----------------------------------------------------------------------------
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS address TEXT;

-- -----------------------------------------------------------------------------
-- 0. auth.users stubs (REQUIRED by profiles_id_fkey).
-- profiles.id references auth.users(id): every profile UUID needs a parent row.
-- Safe to re-run (ON CONFLICT DO NOTHING). Password is a dummy demo hash.
-- -----------------------------------------------------------------------------
